LiftedPoint p[4];
  p[0] = lifted_point(c->vertex(0)->point().x(),
                      c->vertex(0)->point().y(),
                      c->vertex(0)->point().z(),
                      c->vertex(0)->point().w());
  p[1] = lifted_point(c->vertex(1)->point().x(),
                      c->vertex(1)->point().y(),
                      c->vertex(1)->point().z(),
                      c->vertex(1)->point().w());
  p[2] = lifted_point(c->vertex(2)->point().x(),
                      c->vertex(2)->point().y(),
                      c->vertex(2)->point().z(),
                      c->vertex(2)->point().w());
  p[3] = lifted_point(c->vertex(3)->point().x(),
                      c->vertex(3)->point().y(),
                      c->vertex(3)->point().z(),
                      c->vertex(3)->point().w());
  std::array<double, 4> A[4];
  for (int i = 0; i < 4; i++) {
    A[i] = p[i].homogeneous(0);
    A[i + 1] = p[i + 1].homogeneous(1);
    A[i + 2] = p[i + 2].homogeneous(2);
    A[i + 3] = p[i + 3].homogeneous(3);
  }
  // Create hyperplane
  HyperPlane hp = HyperPlane::plane_d();
  // Compute regular triangulation
  RT::Vertex_handle v = c->vertex(0);
  // Get circumcenter
  RT::Vertex_handle vertices[4];
  for (int i = 0; i < 4; i++) {
    if (c->vertex(i) != nullptr) {
      vertices[i] = c->vertex(i);
    }
  }
  // Calculate velocity
  Vector v1 = rt.finite_vertices_begin()->point() - rt.finite_vertices_begin()->point();
  Vector v2 = rt.finite_vertices_begin()->point() + (rt.finite_vertices_begin()->point() - rt.finite_vertices_begin()->point());
  return rt.finite_vertices_begin()->point() + (rt.finite_vertices_begin()->point().x() - rt.fine_vertices_begin()->point().y()) * time;

